WITH cleaned AS (SELECT *, CAST(salary AS INT) salary_int, LENGTH(level) level_length FROM employees WHERE level IS NOT NULL) SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, COUNT(*) FILTER (WHERE job_title = 'Manager') AS manager_rows, SIZE(COLLECT_SET(job_title)) AS num_job_titles, ROUND(AVG(level_length), 2) AS avg_level_length FROM cleaned GROUP BY 1 ORDER BY manager_rows NULLS FIRST
